class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        boolean[] selected = new boolean[profits.length];
        for (int round = 0; round < k; round++) {
            int bestProject = -1;
            for (int project = 0; project < profits.length; project++) {
                if (!selected[project] && capital[project] <= w
                        && (bestProject == -1 || profits[project] > profits[bestProject])) {
                    bestProject = project;
                }
            }
            if (bestProject == -1) break;
            selected[bestProject] = true;
            w += profits[bestProject];
        }
        return w;
    }
}

