import java.util.Arrays;
import java.util.PriorityQueue;

class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        Integer[] order = new Integer[profits.length];
        for (int project = 0; project < order.length; project++) order[project] = project;
        Arrays.sort(order, (first, second) -> Integer.compare(capital[first], capital[second]));

        PriorityQueue<Integer> availableProfits = new PriorityQueue<>((first, second) -> Integer.compare(second, first));
        int nextProject = 0;
        for (int round = 0; round < k; round++) {
            while (nextProject < order.length && capital[order[nextProject]] <= w) {
                availableProfits.offer(profits[order[nextProject]]);
                nextProject++;
            }
            if (availableProfits.isEmpty()) break;
            w += availableProfits.poll();
        }
        return w;
    }
}
